package tests;
import datastructures.WaitingListQueue;import exceptions.InvalidRoomException;import model.Booking;import model.Guest;import model.Room;import service.BookingService;import service.ReservationService;import service.RoomService;import service.TariffService;import java.math.BigDecimal;
public final class AllTests{
 static int passed;private AllTests(){}
 public static void main(String[]a)throws Exception{firstRoom();fifo();promotion();checkoutGuard();tariff();cancellation();inputValidation();inventory();System.out.println("\nAll "+passed+" tests passed.");}
 static void firstRoom()throws Exception{Room r=new RoomService().allocateRoom("Single");check(r.getNumber()==101&&r.isOccupied(),"first room");passed++;}
 static void fifo(){WaitingListQueue q=new WaitingListQueue();Booking a=b(1,"A","Single"),d=b(2,"D","Double"),c=b(3,"C","Single");q.enqueue(a);q.enqueue(d);q.enqueue(c);check(q.removeFirstOfType("Single")==a,"FIFO first");check(q.removeFirstOfType("Single")==c,"FIFO second");check(q.removeFirstOfType("Double")==d&&q.isEmpty(),"queue remaining");passed++;}
 static void promotion()throws Exception{F f=new F();Booking first=null;for(int i=0;i<5;i++){Booking x=f.res.reserve(new Guest("Guest "+i,"98765432"+i),"Single",2);if(i==0)first=x;}check(f.bs.findById(5).getStatus()==Booking.Status.WAITING,"fifth waits");f.bs.checkIn(first.getBookingId());check(f.bs.checkOut(first.getBookingId(),2)!=null,"checkout");f.res.promoteFromWaitingList("Single");Booking x=f.bs.findById(5);check(x.getStatus()==Booking.Status.ALLOCATED&&x.getRoom().getNumber()==101,"promotion");passed++;}
 static void checkoutGuard()throws Exception{F f=new F();Booking x=f.res.reserve(new Guest("G","9876543210"),"Double",1);check(f.bs.checkOut(x.getBookingId(),1)==null,"early checkout rejected");check(x.getStatus()==Booking.Status.ALLOCATED,"status stable");passed++;}
 static void tariff(){F f=new F();Booking b=new Booking(1,new Guest("T","9876543210"),"Suite",5);Room r=f.rooms.findByNumber(301);r.setOccupied(true);b.assignRoom(r);check(f.tariff.generateBill(b,5).compareTo(new BigDecimal("25200.00"))==0,"tariff total");passed++;}
 static void cancellation()throws Exception{F f=new F();for(int i=0;i<5;i++)f.res.reserve(new Guest("C"+i,"98765432"+i),"Double",2);f.res.cancel(1);check(f.bs.findById(1).getStatus()==Booking.Status.CANCELLED,"cancelled");check(f.bs.findById(5).getStatus()==Booking.Status.ALLOCATED,"waiting promoted");check(f.q.isEmpty(),"queue cleared");passed++;}
 static void inputValidation()throws Exception{expect(IllegalArgumentException.class,()->new Guest(" ","9876543210"));expect(IllegalArgumentException.class,()->new Guest("A","123"));F f=new F();expect(IllegalArgumentException.class,()->f.res.reserve(new Guest("A","9876543210"),"Single",0));expect(InvalidRoomException.class,()->f.res.reserve(new Guest("A","9876543210"),"Penthouse",1));passed++;}
 static void inventory(){expect(UnsupportedOperationException.class,()->new RoomService().getRooms().clear());passed++;}
 static Booking b(int id,String n,String t){return new Booking(id,new Guest(n,"9876543210"),t,1);}static void check(boolean c,String m){if(!c)throw new AssertionError(m);}static void expect(Class<? extends Throwable> t,Action a){try{a.run();}catch(Throwable e){if(t.isInstance(e))return;throw new AssertionError(e);}throw new AssertionError("Expected "+t.getSimpleName());}interface Action{void run()throws Exception;}
 static class F{RoomService rooms=new RoomService();TariffService tariff=new TariffService();BookingService bs=new BookingService(tariff);WaitingListQueue q=new WaitingListQueue();ReservationService res=new ReservationService(rooms,bs,q);}
}